  function assertNetwork(userId,networkId,candidateDb){const nid=id(networkId,'id_redes');if(!networkVisible(userId,nid,candidateDb))throw httpError(404,'Registro de Redes no encontrado o fuera de tu alcance.','LAB_SALES_NETWORK_NOT_FOUND');return nid;}
  function networkCatalogs(userId,candidateDb){
    const db=dbOr(candidateDb);
    const read=(area,element,legacyElement)=>{let rows=db.query(`SELECT id_catalogo,area,elemento,articulo,descripcion,orden FROM catalogo_general WHERE activo=1 AND LOWER(TRIM(area))=LOWER(TRIM(?)) AND LOWER(TRIM(elemento))=LOWER(TRIM(?)) ORDER BY orden,articulo,id_catalogo`,[area,element]);if(!rows.length&&legacyElement)rows=db.query(`SELECT id_catalogo,area,elemento,articulo,descripcion,orden FROM catalogo_general WHERE activo=1 AND UPPER(TRIM(area))='REDES' AND UPPER(TRIM(elemento))=? ORDER BY orden,articulo,id_catalogo`,[legacyElement]);return rows;};
    return{contacto_via:read('Ventas','Tipo Contacto','VIA_CONTACTO'),estados:read('General','Estado','ESTADO'),solicitudes:read('Ventas','Soli Red','SOLICITUD'),estatus:read('Ventas','Estatus Pros','ESTATUS'),usuarios:visibleCommercialUsers(userId,db)};
  }
  function listNetworks(userId,query,candidateDb){
    const db=dbOr(candidateDb),scope=networkScopeSql(userId,'r',db),p=pageOf(query,50,500),clauses=['r.activo=1',scope.sql],params=[...scope.params],search=text(query?.search??query?.buscar,250);
    if(search){const like=`%${search}%`;clauses.push('(r.nombre_contacto LIKE ? OR r.email LIKE ? OR r.telefono LIKE ? OR r.nombre_empresa LIKE ? OR r.ciudad LIKE ? OR r.nombre_proyecto LIKE ? OR r.informacion_enviada LIKE ? OR cv.articulo LIKE ? OR ce.articulo LIKE ? OR cs.articulo LIKE ? OR cest.articulo LIKE ? OR u.nombre LIKE ? OR u.iniciales LIKE ? OR q.nombre_proyecto LIKE ? OR q.cliente LIKE ?)');params.push(...Array(15).fill(like));}
    for(const f of ['id_contacto_via','id_estado','id_solicitud','id_usuario_asignado','created_by','id_estatus','id_cotizacion'])if(maybeId(query?.[f])){clauses.push(`r.${f}=?`);params.push(Number(query[f]));}
    if(bool(query?.sin_asignar))clauses.push('r.id_usuario_asignado IS NULL');if(bool(query?.con_asignacion))clauses.push('r.id_usuario_asignado IS NOT NULL');if(bool(query?.sin_cotizacion))clauses.push('r.id_cotizacion IS NULL');if(bool(query?.con_cotizacion))clauses.push('r.id_cotizacion IS NOT NULL');
    const where=clauses.join(' AND '),joins=` LEFT JOIN catalogo_general cv ON cv.id_catalogo=r.id_contacto_via LEFT JOIN catalogo_general ce ON ce.id_catalogo=r.id_estado LEFT JOIN catalogo_general cs ON cs.id_catalogo=r.id_solicitud LEFT JOIN catalogo_general cest ON cest.id_catalogo=r.id_estatus LEFT JOIN usuarios u ON u.id_SB=r.id_usuario_asignado LEFT JOIN usuarios cu ON cu.id_SB=r.created_by LEFT JOIN ventas_cotizaciones_cor q ON q.id_cotizacion=r.id_cotizacion`,total=Number(db.scalar(`SELECT COUNT(DISTINCT r.id_redes) FROM ventas_redes r${joins} WHERE ${where}`,params)||0);
    const rows=db.query(`SELECT r.*,cv.articulo AS contacto_via,cv.descripcion AS contacto_via_descripcion,ce.articulo AS estado,cs.articulo AS solicitud,cs.descripcion AS solicitud_descripcion,cest.articulo AS estatus,cest.descripcion AS estatus_descripcion,u.nombre AS usuario_asignado_nombre,u.iniciales AS usuario_asignado_iniciales,u.puesto AS usuario_asignado_puesto,u.area AS usuario_asignado_area,u.empresa AS usuario_asignado_empresa,cu.nombre AS creado_por_nombre,cu.iniciales AS creado_por_iniciales,q.nombre_proyecto AS cotizacion_nombre,q.cliente AS cotizacion_cliente,q.estatus_proyecto AS cotizacion_estatus,(SELECT COUNT(*) FROM ventas_redes_archivos a WHERE a.id_redes=r.id_redes AND a.activo=1) AS total_evidencias,(SELECT COUNT(*) FROM ventas_redes_comentarios c WHERE c.id_redes=r.id_redes AND c.activo=1) AS total_comentarios FROM ventas_redes r${joins} WHERE ${where} ORDER BY datetime(r.created_at) DESC,r.id_redes DESC LIMIT ? OFFSET ?`,[...params,p.size,p.offset]);
    const totalPages=Math.max(1,Math.ceil(total/p.size));return{registros:rows,data:rows,pagination:{page:p.page,page_size:p.size,total,total_pages:totalPages},paginacion:{pagina:p.page,tamano_pagina:p.size,total,total_paginas:totalPages}};
  }
  function getNetwork(userId,networkId,candidateDb){
    const db=dbOr(candidateDb),nid=assertNetwork(userId,networkId,db),scope=networkScopeSql(userId,'r',db),row=db.query(`SELECT r.*,cv.articulo AS contacto_via,cv.descripcion AS contacto_via_descripcion,ce.articulo AS estado,cs.articulo AS solicitud,cs.descripcion AS solicitud_descripcion,cest.articulo AS estatus,cest.descripcion AS estatus_descripcion,u.nombre AS usuario_asignado_nombre,u.iniciales AS usuario_asignado_iniciales,u.puesto AS usuario_asignado_puesto,u.area AS usuario_asignado_area,u.empresa AS usuario_asignado_empresa,cu.nombre AS creado_por_nombre,cu.iniciales AS creado_por_iniciales,q.nombre_proyecto AS cotizacion_nombre,q.cliente AS cotizacion_cliente,q.estatus_proyecto AS cotizacion_estatus FROM ventas_redes r LEFT JOIN catalogo_general cv ON cv.id_catalogo=r.id_contacto_via LEFT JOIN catalogo_general ce ON ce.id_catalogo=r.id_estado LEFT JOIN catalogo_general cs ON cs.id_catalogo=r.id_solicitud LEFT JOIN catalogo_general cest ON cest.id_catalogo=r.id_estatus LEFT JOIN usuarios u ON u.id_SB=r.id_usuario_asignado LEFT JOIN usuarios cu ON cu.id_SB=r.created_by LEFT JOIN ventas_cotizaciones_cor q ON q.id_cotizacion=r.id_cotizacion WHERE r.id_redes=? AND r.activo=1 AND ${scope.sql} LIMIT 1`,[nid,...scope.params])[0];if(!row)throw httpError(404,'Registro de Redes no encontrado o fuera de tu alcance.');return{...row,archivos:listNetworkFiles(userId,nid,db),comentarios:listNetworkComments(userId,nid,db)};
  }
  async function createNetwork(body,actor,candidateDb){const db=dbOr(candidateDb),uid=actorId(actor),b=values(body),assigned=maybeId(b.id_usuario_asignado)||uid;if(!visibleUser(uid,assigned,db))throw httpError(403,'Responsable fuera de alcance comercial.');const r=await db.run(`INSERT INTO ventas_redes(nombre_contacto,id_contacto_via,email,telefono,id_estado,nombre_empresa,ciudad,nombre_proyecto,informacion_enviada,id_solicitud,id_usuario_asignado,created_by,id_estatus,fecha_cambio_estatus,id_cotizacion,activo,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,?,1,?)`,[text(b.nombre_contacto,180),maybeId(b.id_contacto_via),text(b.email,200),text(b.telefono,80),maybeId(b.id_estado),text(b.nombre_empresa,200),text(b.ciudad,120),text(b.nombre_proyecto,220),text(b.informacion_enviada,3000),maybeId(b.id_solicitud),assigned,uid,maybeId(b.id_estatus),maybeId(b.id_cotizacion),uid]);const nid=Number(r.lastInsertRowId);for(const file of collectFiles(body).slice(0,2))await addNetworkFile(nid,file,uid,db);return getNetwork(uid,nid,db);}
