  function dashboardUsers(userId,candidateDb){return{usuarios:visibleCommercialUsers(userId,candidateDb),visibilidad:coreScope(userId,candidateDb),alcance:coreScope(userId,candidateDb)};}
  function dashboardSelection(userId,query,candidateDb){const db=dbOr(candidateDb),raw=String(query?.usuario_id??'').trim().toLowerCase(),visible=visibleCommercialUsers(userId,db);if(!raw||raw==='todos'||raw==='all')return{mode:'ALL',userId:null,users:visible};const selected=id(raw,'usuario_id');const row=visible.find(item=>Number(item.id_usuario||item.id_SB)===selected);if(!row)throw httpError(403,'El responsable seleccionado queda fuera de tu Alcance de Información de Ventas.','LAB_SALES_DASHBOARD_SCOPE');return{mode:'USER',userId:selected,users:[row]};}
  function dashboardKpis(userId,query,candidateDb){const db=dbOr(candidateDb),selection=dashboardSelection(userId,query,db),effectiveQuery=selection.userId?{...query,id_asesor:selection.userId}:{...query},k=kpisQuotes(userId,effectiveQuery,db).kpis;return{modo:selection.mode,usuario_id:selection.userId,usuarios_incluidos:selection.users.length,anio:Number(query?.anio||new Date().getFullYear()),kpis:{cotizados:{cotizaciones:k.total_cotizaciones,equipos:k.total_equipos},vendidos:{cotizaciones:k.vendidas,equipos:k.equipos_vendidos},perdidos:{cotizaciones:k.perdidas,equipos:k.equipos_perdidos}},anios_disponibles:quoteCatalogs(userId,db).anios};}
  function dashboardTables(userId,query,candidateDb){const db=dbOr(candidateDb),selection=dashboardSelection(userId,query,db),selected=selection.users[0]||null,common={...query,page:1,page_size:100},commercialQuery=selection.userId?{...common,id_asesor:selection.userId}:common,clientQuery=selection.userId?{...common,iniciales:selected?.iniciales||''}:common,prospectQuery=selection.userId?{...common,id_usuario:selection.userId}:common,networkQuery=selection.userId?{...common,id_usuario_asignado:selection.userId}:common;return{modo:selection.mode,usuario_id:selection.userId,usuarios_incluidos:selection.users.length,tablas:{clientes:listClients(userId,clientQuery,db).clientes,cotizaciones:listQuotes(userId,commercialQuery,db).cotizaciones,ventas:quoteByStatus(userId,['Vendido'],commercialQuery,db),perdido:quoteByStatus(userId,['Perdido'],commercialQuery,db),prospeccion:listProspects(userId,prospectQuery,db).prospecciones,redes:listNetworks(userId,networkQuery,db).registros},alcance:coreScope(userId,db)};}
  function dashboardOperation(userId,query,candidateDb){const db=dbOr(candidateDb),raw=String(query?.usuario_id??'').trim().toLowerCase(),scopeIds=visibleUserIds(userId,db);let ids=scopeIds;if(raw&&raw!=='todos'&&raw!=='all'){const selected=id(raw,'usuario_id');if(scopeIds!==null&&!scopeIds.includes(selected))throw httpError(403,'El responsable seleccionado queda fuera de tu Alcance de Información de Ventas.','LAB_SALES_DASHBOARD_SCOPE');ids=[selected];}let assigned=[],created=[],logistica=[],instalaciones=[];if(ids===null){assigned=db.query(`SELECT DISTINCT p.* FROM pendientes p JOIN pendientes_usuarios pu ON pu.id_pendiente=p.id_pendiente ORDER BY p.id_pendiente DESC LIMIT 100`);created=db.query(`SELECT p.* FROM pendientes p ORDER BY p.id_pendiente DESC LIMIT 100`);logistica=db.query('SELECT * FROM logistica_produccion WHERE activo=1 ORDER BY id_produccion DESC LIMIT 100');instalaciones=db.query('SELECT * FROM ins_fl WHERE activo=1 ORDER BY id_ins_fl DESC LIMIT 100');}else if(ids.length){const users=db.query(`SELECT id_SB,iniciales,correo FROM usuarios WHERE estado=1 AND id_SB IN (${sqlIn(ids)})`,ids),initials=[...new Set(users.map(r=>text(r.iniciales,50)).filter(Boolean))],emails=[...new Set(users.map(r=>text(r.correo,200)).filter(Boolean))];if(initials.length)assigned=db.query(`SELECT DISTINCT p.* FROM pendientes p JOIN pendientes_usuarios pu ON pu.id_pendiente=p.id_pendiente WHERE pu.iniciales_usuario IN (${sqlIn(initials)}) ORDER BY p.id_pendiente DESC LIMIT 100`,initials);const creatorClauses=[],creatorParams=[];if(initials.length){creatorClauses.push(`p.creado_por_iniciales IN (${sqlIn(initials)})`);creatorParams.push(...initials);}if(emails.length){creatorClauses.push(`p.creado_por_email IN (${sqlIn(emails)})`);creatorParams.push(...emails);}if(creatorClauses.length)created=db.query(`SELECT p.* FROM pendientes p WHERE (${creatorClauses.join(' OR ')}) ORDER BY p.id_pendiente DESC LIMIT 100`,creatorParams);const ph=sqlIn(ids);logistica=db.query(`SELECT * FROM logistica_produccion WHERE activo=1 AND (id_asesor IN (${ph}) OR id_supervisor IN (${ph}) OR created_by IN (${ph})) ORDER BY id_produccion DESC LIMIT 100`,[...ids,...ids,...ids]);instalaciones=db.query(`SELECT * FROM ins_fl WHERE activo=1 AND (id_asesor IN (${ph}) OR id_sup IN (${ph}) OR id_admin IN (${ph})) ORDER BY id_ins_fl DESC LIMIT 100`,[...ids,...ids,...ids]);}return{tablas:{logistica,instalaciones,tareas_asignadas:assigned,tareas_creadas:created},alcance:coreScope(userId,db)};}

  function dashboardPdfCapabilities(userId,candidateDb){return{ok:true,source:'lab-sqlite',general:true,individual:true,formatos:['GENERAL','INDIVIDUAL'],browser_pdf:true,server_file:false};}
